_TYPE,NULL AD_URL ,NULL Day_of_Week ,YEAR(DATE) AS YEAR ,MONTH(DATE) AS MONTH ,CHANNEL ,FACEBOOK_ACCOUNT AS ACCOUNT ,SUM(CLICKS) Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,sum(reach) Reach ,SUM(CONVERSIONS) Conversions ,SUM(CONVERSION_VALUE) Conversion_Value ,sum(nvl(add_to_carts,0)) Add_to_carts ,sum(nvl(add_to_cart_value,0)) Add_to_cart_value ,sum(nvl(landing_page_views,0)) Landing_page_views ,sum(nvl(initiate_checkouts,0)) Initiate_checkouts ,sum(nvl(initiate_checkouts_value,0)) Initiate_checkouts_value from Snitch_db.MAPLEMONK.Facebook_snitch_CONSOLIDATED group by Ad_Name,ADSET_NAME,ADSET_ID,ACCOUNT_NAME, ACCOUNT_ID ,CAMPAIGN_NAME, CAMPAIGN_ID, DATE, CHANNEL, FACEBOOK_ACCOUNT UNION select * from ( select \"ad_group_ad.ad.name\" as Ad_Name, \"ad_group.name\" as adset_name, \"ad_group_ad.ad.id\" as adset_id, NULL as account_name, null as account_id, \"campaign.name\" as campaign_name, \"campaign.id\"::varchar as campaign_id, \"segments.date\" as date, \"ad_group_ad.ad.type\" as ad_type, NULL as AD_STRENGTH, NULL as AD_NETWORK_TYPE, NULL as AD_URL, null as Day_of_Week, YEAR(\"segments.date\") AS YEAR ,MONTH(\"segments.date\") AS MONTH ,\'Google\' as Channel ,\'Google_Snitch\' ACCOUNT ,SUM(\"metrics.clicks\") Clicks ,SUM(\"metrics.cost_micros\")/1000000 Spend ,SUM(\"metrics.impressions\") Impressions , null as reach ,SUM(\"metrics.conversions\") Conversions ,SUM(\"metrics.conversions_value\") Conversion_Value , null as Add_to_carts ,null as Add_to_cart_value ,null as Landing_page_views ,null as Initiate_checkouts ,null as Initiate_checkouts_value from Snitch_db.MAPLEMONK.ga_spends_updated_campaign_data_ad_level group by Ad_Name,\"ad_group.name\",\"ad_group_ad.ad.id\" ,\"segments.date\",\"campaign.name\", \"campaign.id\" ,\"ad_group_ad.ad.type\", AD_STRENGTH,AD_NETWORK_TYPE,AD_URL, Day_of_Week) qualify row_number() over (partition by Ad_Name,adset_name,adset_id,campaign_id,date,ad_type order by spend desc) = 1 UNION select NULL as Ad_Name, NULL as adset_name, NULL as adset_id, NULL as account_name, NULL as account_id, \"campaign.name\"as campaign_name, \"campaign.id\"::varchar as campaign_id, \"segments.date\" as date, NULL as ad_type, NULL as ad_strength, NULL as ad_network_type, NULL as ad_url, NULL as day_of_week, YEAR(\"segments.date\") YEAR ,MONTH(\"segments.date\") MONTH ,\'Google\' Channel ,\'Google_Snitch\' ACCOUNT ,sum(\"metrics.clicks\") clicks ,sum(\"metrics.cost_micros\")/1000000 spend ,sum(\"metrics.impressions\") impressions , null as reach ,sum(\"metrics.conversions\") conversions ,sum(\"metrics.conversions_value\") conversions_value , null as Add_to_carts ,null as Add_to_cart_value ,null as Landing_page_views ,null as Initiate_checkouts ,null as Initiate_checkouts_value from snitch_db.maplemonk.google_ads_googleads_snitch_campaign_data where \"campaign.advertising_channel_type\" in (\'PERFORMANCE_MAX\',\'SMART\') group by Ad_Name,\"campaign.name\", \"campaign.id\", \"segments.date\" UNION select NULL as Ad_Name, NULL as adset_name, NULL as adset_id, NULL as account_name, NULL as account_id, NULL as campaign_name, null as campaign_id, try_to_date(DATE, \'dd/mm/yyyy\') date, NULL as ad_type, NULL as ad_strength, NULL as ad_network_type, NULL as ad_url, NULL as day_of_week, YEAR(try_to_date(DATE, \'dd/mm/yyyy\')) YEAR ,MONTH(try_to_date(DATE, \'dd/mm/yyyy\')) MONTH ,CHANNEL ,NULL as ACCOUNT, NULL clicks, case WHEN lower(trim(CHANNEL)) = \'sms\' AND try_to_date(DATE, \'dd/mm/yyyy\') < \'2024-07-01\' THEN replace(\"Total Sent\", \',\', \'\')::float * 0.12 WHEN lower(trim(CHANNEL)) = \'sms\' AND try_to_date(DATE, \'dd/mm/yyyy\') >= \'2024-07-01\' THEN replace(\"Total Sent\", \',\', \'\')::float * 0.10 WHEN lower(trim(CHANNEL)) = \'whatsapp\' THEN replace(\"Total Sent\", \',\', \'\')::float * 0.71 WHEN lower(trim(CHANNEL)) = \'whatsapp utility\' THEN replace(\"Total Sent\", \',\', \'\')::float * 0.37 WHEN lower(trim(CHANNEL)) IN (\'push\', \'inapp\') THEN replace(\"Total Sent\", \',\', \'\')::float * 0 ELSE 0 END AS spend, replace(\"Total Sent\",\',\',\'\')::float impressions , null as reach ,NULL conversions ,ifnull(f.gross_Sales,0) + ifnull(g.gross_Sales,0) conversions_value , null as Add_to_carts ,null as Add_to_cart_value ,null as Landing_page_views ,null as Initiate_checkouts ,null as Initiate_checkouts_value from snitch_db.maplemonk.wsms_spends_sheet1 m left join ( select discount_code,sum(gross_sales) gross_sales from snitch_db.maplemonk.order_level_ga_data group by 1 )f on lower(m.code) = lower(f.discount_code) left join ( select sessioncampaignname,sum(gross_sales) gross_sales from snitch_db.maplemonk.order_level_ga_data where lower(final_channel_code) in (\'sms\',\'whatsapp\',\'push\',\'inapp\') and discount_code is null group by 1 )g on lower(m.\"Campaign Name\") = lower(g.sessioncampaignname) UNION select NULL as Ad_Name, NULL as adset_name, NULL as adset_id, NULL as account_name, NULL as account_id, NULL as campaign_name, null as campaign_id, order_timestamp::date as DATE, NULL as ad_type, NULL as ad_strength, NULL as ad_network_type, NULL as ad_url, NULL as day_of_week, YEAR(DATE) AS YEAR ,MONTH(DATE) AS MONTH ,\'Influencers\' AS Channel ,NULL AS ACCOUNT ,NULL AS Clicks ,SUM(discount) Spend ,NULL AS Impressions ,NULL AS Reach ,NULL AS Conversions ,NULL AS Conversion_Value ,NULL AS Add_to_carts ,NULL AS Add_to_cart_value ,NULL AS Landing_page_views ,NULL AS Initiate_checkouts ,NULL AS Initiate_checkouts_value from Snitch_db.MAPLEMONK.fact_items_snitch where lower(discount_code) like \'%influ%\' and is_refund = 0 group by Ad_Name,ADSET_NAME,ADSET_ID,ACCOUNT_NAME, ACCOUNT_ID ,CAMPAIGN_NAME, CAMPAIGN_ID, DATE, CHANNEL, ACCOUNT UNION SELECT NULL as Ad_Name, NULL as adset_name, NULL as adset_id, NULL as account_name, NULL as account_id, NULL as campaign_name, null as campaign_id, order_date AS DATE, NULL as ad_type, NULL as ad_strength, NULL as ad_network_type, NULL as ad_url, NULL as day_of_week, EXTRACT(YEAR FROM order_date) AS YEAR, EXTRACT(MONTH FROM orde